// Localization.h • Interface language support for AntiAFK-RBX (English / Russian).
// English is the source language: UI strings stay in English in AntiAFK-RBX.cpp and are passed through TR().
// Russian translation by x0doit.
#pragma once

#include <windows.h>
#include <atomic>
#include <cwchar>
#include <iterator>
#include <string>
#include <string_view>
#include <unordered_map>

enum class UiLanguage : int
{
    Unset = 0,
    English = 1,
    Russian = 2,
};

inline std::atomic<int> g_uiLanguage{ (int)UiLanguage::Unset };

inline constexpr wchar_t kLanguageSettingTitle[] = L"Language / Язык";
inline constexpr wchar_t kLanguageNameEnglish[] = L"English";
inline constexpr wchar_t kLanguageNameRussian[] = L"Русский (перевод: x0doit)";
inline constexpr wchar_t kLanguageNameRussianShort[] = L"Русский (x0doit)";

// Windows display language decides the default: Russian systems start in Russian, everything else in English.
inline int DetectSystemUiLanguage()
{
    return PRIMARYLANGID(GetUserDefaultUILanguage()) == LANG_RUSSIAN ? (int)UiLanguage::Russian : (int)UiLanguage::English;
}

// Saved choice (HKCU\Software\Agzes\AntiAFK-RBX\Language), or the system language when nothing is saved yet.
inline int LoadSavedUiLanguage()
{
    DWORD value = 0;
    DWORD size = sizeof(value);
    if (RegGetValueW(HKEY_CURRENT_USER, L"Software\\Agzes\\AntiAFK-RBX", L"Language", RRF_RT_REG_DWORD, nullptr, &value, &size) == ERROR_SUCCESS &&
        (value == (DWORD)UiLanguage::English || value == (DWORD)UiLanguage::Russian))
    {
        return (int)value;
    }
    return DetectSystemUiLanguage();
}

inline void SaveUiLanguage(int language)
{
    DWORD value = (DWORD)language;
    RegSetKeyValueW(HKEY_CURRENT_USER, L"Software\\Agzes\\AntiAFK-RBX", L"Language", REG_DWORD, &value, sizeof(value));
}

inline int GetUiLanguage()
{
    int language = g_uiLanguage.load(std::memory_order_relaxed);
    if (language == (int)UiLanguage::Unset)
    {
        language = LoadSavedUiLanguage();
        g_uiLanguage.store(language, std::memory_order_relaxed);
    }
    return language;
}

inline bool IsRussianUi()
{
    return GetUiLanguage() == (int)UiLanguage::Russian;
}

